namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;
    private const int WelcomeFiveCents = 500;
    private const int SummerTenCapCents = 1_500;

    public static int DiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyalty = LoyaltyCents(subtotalCents, tier);
        var promo = PromoCents(subtotalCents - loyalty, promoCode);
        return Math.Min(subtotalCents, loyalty + promo);
    }

    private static int LoyaltyCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(LoyaltyCapCents, subtotalCents * RatePercent(tier) / 100);

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => 0
    };

    private static int PromoCents(int remainingCents, string? promoCode) =>
        promoCode?.ToUpperInvariant() switch
        {
            "WELCOME5" => WelcomeFiveCents,
            "SUMMER10" => Math.Min(SummerTenCapCents, remainingCents / 10),
            _ => 0
        };
}
EOF
cat > src/CheckoutPricing.Domain/ShippingFeePolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressCents(tier) : StandardCents(payableTotalCents, tier);

    private static int ExpressCents(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardCents(int payableTotalCents, LoyaltyTier tier) =>
        tier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromCents ? 0 : StandardFeeCents;
}
EOF
cd src/CheckoutPricing.Application
python3 - <<'EOF'
p='CalculateLoyaltyDiscount.cs'
s=open(p).read()
s=s.replace("""    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query) =>
        new(query.SubtotalCents, 0, query.SubtotalCents, query.LoyaltyTier);""","""    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
    {
        var discount = LoyaltyDiscountPolicy.DiscountCents(query.SubtotalCents, query.LoyaltyTier, query.PromoCode);
        return new(query.SubtotalCents, discount, query.SubtotalCents - discount, query.LoyaltyTier);
    }""")
open(p,'w').write(s)
p='CalculateShippingFee.cs'
s=open(p).read()
s=s.replace("=> 0;","=>\n        ShippingFeePolicy.FeeCents(query.PayableTotalCents, query.LoyaltyTier, query.Express);")
open(p,'w').write(s)
p='QuoteCheckout.cs'
s=open(p).read()
s=s.replace("""    public CheckoutQuote Handle(QuoteCheckoutQuery query) => new(0, 0, 0);""","""    public CheckoutQuote Handle(QuoteCheckoutQuery query)
    {
        var discount = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(query.SubtotalCents, query.LoyaltyTier, query.PromoCode));
        var shipping = new CalculateShippingFee()
            .Handle(new CalculateShippingFeeQuery(discount.TotalCents, query.LoyaltyTier, query.Express));
        return new(discount.TotalCents, shipping, discount.TotalCents + shipping);
    }""")
open(p,'w').write(s)
EOF
cd ../.. && dotnet build CheckoutPricing.slnx --no-restore -v q 2>&1 | tail -3; dotnet test CheckoutPricing.slnx --no-restore --verbosity quiet 2>&1 | tail -8

